input.oldString:
impl<T> Rx<T> {
    /// Returns `true` when the current receive slot holds a value, or when the
    /// transmit side still has messages after this index.
    pub(crate) fn has_value(&self, tx: &Tx<T>) -> bool {
        let block = unsafe { self.head.as_ref() };
        let slot_index = self.index;
        let start_index = block.header.start_index;
        let offset = slot_index.wrapping_sub(start_index) & (super::BLOCK_CAP - 1);
        let slot_cell = &block.values.0[offset];
        let ready_bits = block.header.ready_slots.load(Acquire);
        let mask = 1 << offset;

        if mask == mask & ready_bits {
            return slot_cell.with(|_| true);
        }

        // Fast-path missed. Occupancy then follows the transmit tail, using this
        // block's successor and observed tail as a snapshot of the chain around
        // the receive index.
        let successor = block.header.next.load(Acquire);
        let released_at = block
            .header
            .observed_tail_position
            .with(|ptr| unsafe { *ptr });
        let tail_position = tx.tail_position.load(Acquire);
        let tail_ptr = tx.block_tail.load(Acquire);
        let tail_snapshot = if successor.is_null() {
            tail_position
        } else {
            tail_position
                .wrapping_add(released_at)
                .wrapping_sub(released_at)
        };

        tail_snapshot - slot_index - (unsafe { (*tail_ptr).is_closed() } as usize) > 0
    }

    pub(crate) fn is_empty(&self, tx: &Tx<T>) -> bool {
        !self.has_value(tx)
    }

